 function restorePresentation(){cancelReveal();ui.reveal=null;clock.resume();const savedReveal=s.dynasty.v8Reveal,view=X.screen();setView(view==='world'?'clubs':view);if(savedReveal&&savedReveal.year===s.year&&savedReveal.count<=8){if(savedReveal.kind==='league'){setView('leagueDraw');startReveal('league',savedReveal);}else if(savedReveal.kind==='draft'){window.GCC8_FOUNDATION_READ.pauseDraft();setView('draftDraw');startReveal('draft',savedReveal);}else if(savedReveal.kind==='annual'&&s.dynasty.offseason?.phase==='lottery'){setView('dynasty');startReveal('annual',savedReveal);}render(false);}else if(view==='dynasty'&&s.dynasty.offseason?.phase==='lottery'){startReveal('annual',{count:8,running:false});render(false);}const savedUI=s.dynasty.v8UI;if(savedUI){ui.teamReturn=savedUI.teamReturn;ui.seasonTab=savedUI.seasonTab;ui.result=s.results.find(r=>r.round===savedUI.resultRound)||null;archiveReturn=views[savedUI.archiveReturn]?savedUI.archiveReturn:'season';if(savedUI.view==='team'&&s.fullSchedule.length){G.go('team');setView('team');}else if(savedUI.view==='result'&&!savedUI.resultFinal){ui.result=s.results.find(r=>r.round===savedUI.resultRound);if(ui.result)setView('result');}else if(savedUI.view==='archive')setView('archive');render(false);}else if(view==='archive')archiveReturn=s.dynasty.careerClosed?'legacy':s.dynasty.offseason?'dynasty':s.dynasty.archiveReturnScreen||'season';cancelMatchTimer();ui.match=null;const savedMatch=s.dynasty.v8Match;if(savedMatch&&savedMatch.year===s.year){const r=matchFromReference(savedMatch.reference);if(r){ui.match={...savedMatch};ui.result=r;if(savedUI?.view==='matchReveal')beginMatch(r,savedMatch.returnView,savedMatch);}}if(annual())D.runCpuDraftUntilUser(false);}
