 bind('postSeason',['season'],()=>{assert(s.round===14,'Finish the regular season first.');if(s.regularSeasonPosition<=4&&read.xiProblem()){ui.teamReturn='season';G.go('team');setView('team');announce('Review availability and name your finals XI.');return;}G.proceedPostSeason();setView(X.screen());if(ui.view==='review')read.archive();});
 bind('simulateFinals',['finals'],()=>{assert(['ready','gf-ready'].includes(s.finals?.stage),'The next finals match is not ready.');const stageBefore=s.finals.stage,managementContext=X.managementBefore();G.simulateFinals();assert(s.finals.stage!==stageBefore,'Review your XI before the finals match.');const r=s.finals.stage==='semis'?s.finals.semis.find(r=>[r.home.abbr,r.away.abbr].includes(own()))||s.finals.semis[0]:s.finals.gf;X.managementAfter(managementContext,r);beginMatch(r,'finals');});
 bind('advanceFinals',['finals'],()=>{assert(s.finals?.stage==='semis','Play the semi-finals first.');G.advanceFinals();});
